/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`%`*/ /*!50003 TRIGGER `trg_expense_approved_update_budget` AFTER UPDATE ON `expense` FOR EACH ROW BEGIN
    IF OLD.status <> '已通过' AND NEW.status = '已通过' THEN
        UPDATE project
        SET used_budget = used_budget + NEW.amount
        WHERE project_id = NEW.project_id;
    END IF;
END */;;
