--
-- Table structure for table `project`
--

DROP TABLE IF EXISTS `project`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `project` (
  `project_id` int NOT NULL AUTO_INCREMENT,
  `project_name` varchar(200) NOT NULL,
  `leader_id` int NOT NULL,
  `teacher_id` int DEFAULT NULL,
  `project_type` enum('创新训练','创业训练','创业实践') NOT NULL,
  `project_level` enum('未定级','校级','省级','国家级') DEFAULT '未定级',
  `status` enum('待评审','已立项','进行中','待结题','已结题','已驳回') DEFAULT '待评审',
  `budget` decimal(10,2) DEFAULT '0.00',
  `used_budget` decimal(10,2) DEFAULT '0.00',
  `apply_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `description` text,
  PRIMARY KEY (`project_id`),
  KEY `leader_id` (`leader_id`),
  KEY `teacher_id` (`teacher_id`),
  CONSTRAINT `project_ibfk_1` FOREIGN KEY (`leader_id`) REFERENCES `student` (`student_id`),
  CONSTRAINT `project_ibfk_2` FOREIGN KEY (`teacher_id`) REFERENCES `teacher` (`teacher_id`),
  CONSTRAINT `project_chk_1` CHECK ((`budget` >= 0)),
  CONSTRAINT `project_chk_2` CHECK ((`used_budget` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

