/*!50003 DROP PROCEDURE IF EXISTS `sp_project_detail` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sp_project_detail`(IN pid INT)
BEGIN
    SELECT 
        p.project_id,
        p.project_name,
        p.project_type,
        p.project_level,
        p.status,
        p.budget,
        p.used_budget,
        p.apply_time,
        p.description,
        s.name AS leader_name,
        s.college AS leader_college,
        s.major AS leader_major,
        t.name AS teacher_name,
        t.title AS teacher_title
    FROM project p
    JOIN student s ON p.leader_id = s.student_id
    LEFT JOIN teacher t ON p.teacher_id = t.teacher_id
    WHERE p.project_id = pid;

    SELECT 
        tm.member_id,
        s.name AS student_name,
        s.student_no,
        tm.duty
    FROM team_member tm
    JOIN student s ON tm.student_id = s.student_id
    WHERE tm.project_id = pid;

    SELECT 
        r.score,
        r.opinion,
        r.review_result,
        r.review_time,
        t.name AS reviewer_name
    FROM review r
    JOIN teacher t ON r.teacher_id = t.teacher_id
    WHERE r.project_id = pid;

    SELECT 
        report_title,
        report_type,
        status,
        submit_time
    FROM progress_report
    WHERE project_id = pid;

    SELECT 
        expense_type,
        amount,
        status,
        apply_time,
        approve_time
    FROM expense
    WHERE project_id = pid;

    SELECT 
        achievement_type,
        achievement_name,
        achievement_date
    FROM achievement
    WHERE project_id = pid;
END ;;
DELIMITER ;
